mapper.delete:
DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}

mapper.select:
SELECT count(*)
  FROM ics31_compliance_write
 WHERE ics31_person_id  = #{personId}
   AND ics31_yyyymm     = TO_CHAR(#{stdDate}::date,'YYYY.MM')
   AND ics31_cycle_type = #{cycleType}
   AND ics31_fix_yn     = 'true'

SELECT STRING_AGG(COALESCE(ics31_reason,''),' ')
  FROM ics31_compliance_write
       INNER JOIN ics30_compliance ON ics30_compliance_id = ics31_compliance_id
 WHERE ics31_person_id       = #{personId}
   AND ics31_yyyymm          = TO_CHAR(#{stdDate}::date,'YYYY.MM')
   AND ics31_cycle_type      = #{cycleType}
   AND ics30_compliance_type = #{complianceType}

SELECT ics32_relate_appr_id                                                              AS relate_appr_id,
       ics32_appr_id                                                                     AS appr_id,
       b.apr01_status_cd                                                                 AS status_code,
       f_cdnm('AprStatusCode', b.apr01_status_cd, ics32_company_id, b.apr01_reg_date)    AS status_name
  FROM ics32_relate_appr
       LEFT OUTER JOIN apr01_appr b ON ics32_appr_id = apr01_appr_id
 WHERE ics32_company_id = #{companyId}
   AND ics32_yyyymm     = #{yyyymm}
   AND ics32_cycle_type = #{cycleType}
   AND ics32_appr_type  = #{apprType}

    AND ics32_person_id = #{personId}
    AND ics32_person_id IS NULL

 LIMIT 1

SELECT ics32_relate_appr_id
  FROM ics32_relate_appr
 WHERE ics32_company_id = #{companyId}
   AND ics32_yyyymm     = #{yyyymm}
   AND ics32_cycle_type = #{cycleType}
   AND ics32_appr_type  = #{apprType}

    AND ics32_person_id = #{personId}
    AND ics32_person_id IS NULL

 LIMIT 1

mapper.update:
UPDATE ics32_relate_appr
   SET ics32_appr_id = #{apprId}
 WHERE ics32_relate_appr_id = #{relateApprId}
   AND ics32_company_id     = #{companyId}
